<template lang="pug">
.PieceCount.is-unselectable(v-if="count >= 2")
  | {{count}}
</template>

<script>
import { support } from "./support.js"

export default {
  name: "PieceCount",
  mixins: [support],
  props: {
    count: { type: Number, required: true },
  },
}
</script>

<style lang="sass">
@import "./support"

.ShogiPlayer
  +defvar(sp_piece_count_horizontal_x, 0.43)                // 駒数の中央からの相対位置X(%) (左右配置時)
  +defvar(sp_piece_count_horizontal_y, 0.30)                // 駒数の中央からの相対位置Y(%) (左右配置時)
  +defvar(sp_piece_count_vertical_x, 0.0)                   // 駒数の中央からの相対位置X(%) (上下配置時)
  +defvar(sp_piece_count_vertical_y, 0.47)                  // 駒数の中央からの相対位置y(%) (上下配置時)
  +defvar(sp_piece_count_size, 0.25)                        // 駒数の文字サイズ(駒セル縦幅に対する比率)
  +defvar(sp_piece_count_font_color, hsl(0 0% 0% / 0.75))   // 駒数の文字色
  +defvar(sp_piece_count_bg_color, hsl(0 0% 100% / 0.9))    // 駒数の文字色背景
  +defvar(sp_piece_count_padding, 0.08)                     // 駒数のパディング(駒セル縦幅に対する比率)
  +defvar(sp_piece_count_border_width, 0.0)                 // 駒数の外枠ピクセル数
  +defvar(sp_piece_count_border_color, hsl(0 0% 0% / 0.1))  // 駒数の外枠色

  //////////////////////////////////////////////////////////////////////////////// 本当に共通のもの

  .PieceObject
    display: flex               // PieceCount を中央配置させるため
    justify-content: center
    align-items: center

  .MembershipStand
    .PieceCount
      font-size: calc(var(--sp_stand_cell_current_h) * var(--sp_piece_count_size))
      padding:   calc(var(--sp_stand_cell_current_w) * var(--sp_piece_count_padding)) calc(var(--sp_stand_cell_current_h) * var(--sp_piece_count_padding))

  .PieceBox
    .PieceCount
      font-size: calc(var(--sp_piece_box_cell_current_h) * var(--sp_piece_count_size))
      padding:   calc(var(--sp_piece_box_cell_current_w) * var(--sp_piece_count_padding)) calc(var(--sp_piece_box_cell_current_h) * var(--sp_piece_count_padding))

  .PieceCount
    @extend %is_piece_count_color_set

    line-height: 1.0
    border-radius: 50%
    font-weight: bold
    border: calc(var(--sp_piece_count_border_width) * 1px) solid var(--sp_piece_count_border_color)

    z-index: $piece_count_z // 駒数が Membership の下に潜るのを防ぐ (FIXME: これは本当に必要？)
    position: relative      // 相対的にずらすため、かつ z-index 用

    pointer-events: none    // タップの邪魔をしないようにするため。

  &.is_layer_on
    .PieceCount
      +is_layer_border

  //////////////////////////////////////////////////////////////////////////////// 全体横並びの場合は横に広く表示
  +IF_HORIZONTAL
    .Membership
      &.is_position_north
        .PieceCount
          +is_flip // 上下対象にするため(反転時にそのままでよくなるが、先手からは読みにくい)
          right:   calc(var(--sp_piece_count_horizontal_x) * 100%)
          bottom:  calc(var(--sp_piece_count_horizontal_y) * 100%)
      &.is_position_south
        .PieceCount
          left:  calc(var(--sp_piece_count_horizontal_x) * 100%)
          top:   calc(var(--sp_piece_count_horizontal_y) * 100%)

  //////////////////////////////////////////////////////////////////////////////// 全体縦並びの場合

  +IF_VERTICAL
    .Membership
      &.is_position_north
        .PieceCount
          +is_flip // 上下対象にするため(反転時にそのままでよくなるが、先手からは読みにくい)
          right:  calc(var(--sp_piece_count_vertical_x) * 100%)
          bottom: calc(var(--sp_piece_count_vertical_y) * 100%)
      &.is_position_south
        .PieceCount
          left: calc(var(--sp_piece_count_vertical_x) * 100%)
          top:  calc(var(--sp_piece_count_vertical_y) * 100%)

  //////////////////////////////////////////////////////////////////////////////// 駒箱
  .PieceBox
    .PieceCount
      left: calc(var(--sp_piece_count_vertical_x) * 100%)
      top:  calc(var(--sp_piece_count_vertical_y) * 100%)
</style>
